<?php $details = $page['paymentDetails']; $available = bcsub($record['total_amount'], bcadd($details['settled'], $details['pending'], 2), 2); ?>
<dl class="quotation-totals"><div><dt>Pagado</dt><dd><?= accountingEscape($details['settled']) ?></dd></div><div><dt>En proceso</dt><dd><?= accountingEscape($details['pending']) ?></dd></div><div><dt>Saldo sin pagar</dt><dd><?= accountingEscape($details['reversal'] ? '0.00' : bcsub($record['total_amount'], $details['settled'], 2)) ?></dd></div></dl>
<?php if ($record['status'] === 'posted' && ! $details['reversal'] && bccomp($available, '0', 2) > 0): ?>
    <form method="post" action="index.php?type=<?= $page['type'] ?>&amp;id=<?= (int) $record['id'] ?>"><input type="hidden" name="csrf" value="<?= accountingEscape($page['csrf']) ?>"><input type="hidden" name="version" value="<?= (int) $record['version'] ?>"><input type="hidden" name="action" value="register_payment"><div class="contact-form-grid">
        <label>Importe del pago *<input name="amount" inputmode="decimal" required value="<?= accountingEscape($available) ?>" maxlength="19"></label><label>Fecha de pago *<input type="date" name="payment_date" required value="<?= commerceToday() ?>"></label><label>Referencia<input name="reference" maxlength="160"></label>
    </div><button class="contact-button contact-button-primary" type="submit">Registrar pago</button><p class="section-subtitle">El pago queda en proceso hasta que lo confirmes.</p></form>
<?php endif; ?>
<div class="contact-table-wrap"><table class="contact-table"><thead><tr><th scope="col">Fecha</th><th scope="col">Referencia</th><th scope="col">Importe</th><th scope="col">Estado</th><th scope="col">Acciones</th></tr></thead><tbody>
    <?php foreach ($details['payments'] as $payment): ?><tr><td><?= accountingEscape($payment['payment_date']) ?></td><td><?= accountingEscape($payment['reference']) ?></td><td><?= accountingEscape($payment['amount']) ?></td><td><?= match ($payment['status']) { 'pending' => 'En proceso de pago', 'settled' => 'Confirmado', default => 'Cancelado' } ?></td><td>
        <?php if ($record['status'] === 'posted' && ! $details['reversal'] && $payment['status'] !== 'cancel'): ?><form method="post" action="index.php?type=<?= $page['type'] ?>&amp;id=<?= (int) $record['id'] ?>"><input type="hidden" name="csrf" value="<?= accountingEscape($page['csrf']) ?>"><input type="hidden" name="version" value="<?= (int) $record['version'] ?>"><input type="hidden" name="payment_id" value="<?= (int) $payment['id'] ?>"><?php if ($payment['status'] === 'pending'): ?><button class="contact-button" type="submit" name="action" value="settle_payment">Confirmar pago</button><?php endif; ?><button class="contact-button" type="submit" name="action" value="cancel_payment">Cancelar pago</button></form><?php endif; ?>
    </td></tr><?php endforeach; ?><?php if (! $details['payments']): ?><tr><td colspan="5" class="contact-empty">No hay pagos registrados.</td></tr><?php endif; ?>
</tbody></table></div>
<?php if ($details['reversal']): ?><p class="notice" role="status">Revertido · <?= accountingEscape($details['reversal']['name']) ?> · <?= accountingEscape($details['reversal']['reversal_date']) ?> · <?= accountingEscape($details['reversal']['reason']) ?> · Importe: <?= accountingEscape($details['reversal']['amount']) ?></p>
<?php elseif ($record['status'] === 'posted' && bccomp(bcadd($details['settled'], $details['pending'], 2), '0', 2) === 0): ?><form method="post" action="index.php?type=<?= $page['type'] ?>&amp;id=<?= (int) $record['id'] ?>"><input type="hidden" name="csrf" value="<?= accountingEscape($page['csrf']) ?>"><input type="hidden" name="version" value="<?= (int) $record['version'] ?>"><input type="hidden" name="action" value="reverse_invoice"><label>Motivo de reversión *<input name="reason" required maxlength="255"></label><button class="contact-button" type="submit">Revertir factura</button></form><?php endif; ?>
